//! Entry-by-entry array programs under every engine: `*` and `/` of arrays
//! of one shape, scaling, unary minus, the math functions of arrays, and the
//! reductions back to numbers, generated by `generate_arrays` in the
//! differential fuzzer's harness (`fuzz/harness/differential.rs`; that
//! generator also feeds about one program in five of the shared fuzzers).
//!
//! Every program type-checks by construction, and some fail on purpose (an
//! overflow, a zero divisor or a domain error at some entries only). For
//! each one:
//!
//! * the harness oracle (`check_source`): the tree-walker, the lowered SIR,
//!   the SIR after the default pipeline (which fuses the chains) and native
//!   code on both give one stdout and one rendered diagnostic, and the SIR
//!   text round-trips;
//! * every pass of the pipeline, run one at a time on the lowered SIR, keeps
//!   the outcome (so a single pass is blamed);
//! * the optimized SIR runs the same with native kernels for every `fused`
//!   (`JitOptions::ALWAYS`), with the interpreter's loop only (`OFF`), and
//!   in parallel with every threshold at its minimum, so kernels of a few
//!   entries take the chunked paths (`Config::eager`), on 2, 4 and 8
//!   threads and with the chunks at small sizes.
//!
//! About one program in four has a vector of 520 to 700 entries, so the
//! native kernels run at their default threshold too.
//!
//! `SKY_FUZZ_FROM` and `SKY_FUZZ_SEEDS` run a longer campaign (use
//! `--release`): `SKY_FUZZ_SEEDS=50000 cargo test --release -p sky-opt --test
//! fuzz_elementwise -- --nocapture`. `SKY_FUZZ_KEEP_GOING=1` lists every
//! failing seed instead of stopping at the first; `SKY_SEED=n` prints the
//! program for seed `n`.

#[path = "../../../fuzz/harness/differential.rs"]
mod harness;

use sky_diag::SourceFile;
use sky_ir::parallel::Config;
use sky_ir::{Module, PassManager};
use sky_ir_interp::JitOptions;

/// A deterministic byte stream for a seed: xorshift64*.
fn bytes(seed: u64, len: usize) -> Vec<u8> {
    let mut x = seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1;
    (0..len)
        .map(|_| {
            x ^= x >> 12;
            x ^= x << 25;
            x ^= x >> 27;
            (x.wrapping_mul(0x2545_F491_4F6C_DD1D) >> 56) as u8
        })
        .collect()
}

fn env_number(name: &str) -> Option<u64> {
    std::env::var(name).ok().and_then(|v| v.parse().ok())
}

/// The program for `seed`. The lengths vary so programs of every size
/// appear.
fn program(seed: u64) -> String {
    let len = 120 + (seed.wrapping_mul(2_654_435_761) % 900) as usize;
    harness::generate_arrays(&bytes(seed, len))
}

/// Stdout and the rendered error.
type Outcome = (String, Option<String>);

fn outcome(out: Vec<u8>, err: Option<sky_ir_interp::IrRuntimeError>, src: &str) -> Outcome {
    (
        String::from_utf8_lossy(&out).into_owned(),
        err.map(|e| {
            e.to_diagnostic()
                .render_to_string(&SourceFile::new("p.sky", src))
        }),
    )
}

fn run(m: &Module, src: &str, cfg: &Config) -> Outcome {
    let mut out = Vec::new();
    let r = sky_ir_interp::run_with(m, &mut out, cfg);
    outcome(out, r.err(), src)
}

fn run_jit(m: &Module, src: &str, jit: JitOptions) -> Outcome {
    let mut out = Vec::new();
    let r = sky_ir_interp::call_with_jit(m, Module::MAIN, Vec::new(), &mut out, jit);
    outcome(out, r.err(), src)
}

fn differs(what: &str, want: &Outcome, got: &Outcome, m: &Module) -> String {
    format!(
        "{what} differs\n--- expected ---\n{}{}\n--- got ---\n{}{}\n--- SIR text ---\n{}",
        want.0,
        want.1.as_deref().unwrap_or("(ok)"),
        got.0,
        got.1.as_deref().unwrap_or("(ok)"),
        sky_ir::print(m)
    )
}

fn check(src: &str) -> Result<(), String> {
    // The tree-walker, lowered SIR, optimized SIR, native, SIR text.
    harness::check_source(src)?;

    let mut ir = sky_lower::lower_source(src).map_err(|e| format!("lowering: {e}"))?;
    let want = run(&ir, src, &Config::sequential());

    // Every pass alone.
    for pass in sky_opt::DEFAULT_PASSES {
        let one = match pass {
            "fold" => PassManager::new().with(sky_opt::FoldPass::default()),
            "egraph" => PassManager::new().with(sky_egraph::EgraphPass::default()),
            "contracts" => PassManager::new().with(sky_opt::ContractsPass),
            "dce" => PassManager::new().with(sky_opt::DcePass),
            "powers" => PassManager::new().with(sky_opt::PowersPass),
            "fuse" => PassManager::new().with(sky_opt::FusePass),
            "transposes" => PassManager::new().with(sky_opt::TransposesPass),
            "structure" => PassManager::new().with(sky_opt::StructurePass),
            "algorithms" => PassManager::new().with(sky_opt::AlgorithmPass::default()),
            "specialize" => PassManager::new().with(sky_opt::SpecializePass),
            _ => PassManager::new().with(sky_opt::CholeskyPass),
        };
        let mut m = ir.clone();
        one.verify_each(true)
            .run(&mut m)
            .map_err(|e| format!("the pass `{pass}` broke the IR: {e}"))?;
        let got = run(&m, src, &Config::sequential());
        if got != want {
            return Err(differs(&format!("after `{pass}` the run"), &want, &got, &m));
        }
    }

    // The whole pipeline, then the run under every engine setting.
    sky_opt::default_passes(PassManager::new().verify_each(true))
        .run(&mut ir)
        .map_err(|e| format!("a pass broke the IR: {e}"))?;
    let got = run(&ir, src, &Config::sequential());
    if got != want {
        return Err(differs("the optimized run", &want, &got, &ir));
    }
    for (name, jit) in [
        ("native kernels", JitOptions::ALWAYS),
        ("no kernels", JitOptions::OFF),
    ] {
        let got = run_jit(&ir, src, jit);
        if got != want {
            return Err(differs(name, &want, &got, &ir));
        }
    }
    let mut configs = Vec::new();
    for t in [2, 4, 8] {
        configs.push(Config::eager(t));
        configs.push(Config::with_threads(t));
    }
    configs.push(Config {
        chunk_min: 3,
        ..Config::eager(4)
    });
    for cfg in configs {
        let got = run(&ir, src, &cfg);
        if got != want {
            return Err(differs(
                &format!("the run on {} threads", cfg.threads),
                &want,
                &got,
                &ir,
            ));
        }
    }
    Ok(())
}

#[test]
fn generated_array_programs_agree_in_every_engine() {
    if let Some(seed) = env_number("SKY_SEED") {
        println!("{}", program(seed));
    }
    let first = env_number("SKY_FUZZ_FROM").unwrap_or(1);
    let count = env_number("SKY_FUZZ_SEEDS").unwrap_or(400);
    let lanes = std::thread::available_parallelism().map_or(1, |n| n.get().min(8)) as u64;
    let keep_going = std::env::var("SKY_FUZZ_KEEP_GOING").is_ok();
    let failures: Vec<String> = std::thread::scope(|scope| {
        let handles: Vec<_> = (0..lanes)
            .map(|lane| {
                scope.spawn(move || {
                    let mut failures = Vec::new();
                    let mut seed = first + lane;
                    while seed < first + count {
                        let src = program(seed);
                        if let Err(msg) = sky_ast::with_deep_stack(|| check(&src)) {
                            failures.push(format!("seed {seed}: {msg}\n--- program ---\n{src}"));
                            if !keep_going {
                                break;
                            }
                        }
                        seed += lanes;
                    }
                    failures
                })
            })
            .collect();
        handles
            .into_iter()
            .flat_map(|h| h.join().expect("a lane panicked"))
            .collect()
    });
    let summary: Vec<&str> = failures
        .iter()
        .map(|f| f.lines().next().unwrap_or(""))
        .collect();
    assert!(
        failures.is_empty(),
        "{} failure(s): {summary:#?}\nfirst:\n{}",
        failures.len(),
        failures[0]
    );
}

/// The generator makes programs that check, fuse, and fail in some (not all)
/// of the cases, or it would test nothing.
#[test]
fn the_generator_reaches_kernels_failures_and_long_arrays() {
    let (mut fused, mut failed, mut ok, mut long, mut math_fused) = (0, 0, 0, 0, 0);
    for seed in 1..=300 {
        let src = program(seed);
        let mut ir = sky_lower::lower_source(&src).unwrap_or_else(|e| panic!("{e}\n{src}"));
        sky_opt::default_passes(PassManager::new().verify_each(true))
            .run(&mut ir)
            .expect("the pipeline verifies");
        let text = sky_ir::print(&ir);
        if text.contains("fused") {
            fused += 1;
            if text.contains("math.") && text.contains("^1(") {
                math_fused += 1;
            }
        }
        if src.contains("Vector[5") || src.lines().any(|l| l.len() > 1500) {
            long += 1;
        }
        let r = sky_ast::with_deep_stack(|| run(&ir, &src, &Config::sequential()));
        if r.1.is_some() {
            failed += 1;
        } else {
            ok += 1;
        }
    }
    eprintln!("300 programs: {fused} fuse ({math_fused} with math), {failed} fail, {ok} succeed, {long} long");
    assert!(fused > 100, "only {fused} of 300 programs fuse");
    assert!(failed > 20, "only {failed} of 300 programs fail");
    assert!(ok > 100, "only {ok} of 300 programs succeed");
    assert!(long > 20, "only {long} programs have a long array");
}
